fn pre_width_getter_html_integer_prefixes_defaults_and_exact_namespaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:listing')]){x.removeAttribute('width');if(x.width!==0)throw 'absent long default';x.setAttributeNS('urn:foreign','width','91');x.setAttributeNS(null,'WIDTH','92');if(x.width!==0)throw 'exact long namespace and case';for(var pair of [['',0],['  +0031tail',31],['-2147483648x',-2147483648],['2147483647.9',2147483647],['2147483648',0],['-2147483649',0],['0x10',0],['3.9',3],['-.1',0],['--1',0],['\u00a0 3',0],[' \t\n\f\r-0junk',0],['+0000030tail',30],['+',0],['-1e10',-1],['0000000000000000012',12]]){x.setAttributeNS(null,'width',pair[0]);var attr=x.getAttributeNodeNS(null,'width');if(typeof x.width!=='number'||x.width!==pair[1]||attr.value!==pair[0]||x.getAttributeNodeNS(null,'width')!==attr)throw 'HTML long prefix without normalization';}x.setAttributeNS(null,'width','-0');if(1/x.width!==Infinity)throw 'positive zero read';}"#);}
