#[test]
fn pre_width_once_number_conversion_reentry_abrupt_and_non_number_primitives(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),old=x.getAttributeNode('width'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.width={valueOf:function(){calls++;x.removeAttribute('width');x.setAttribute('width','author');return 2147483648;},toString:function(){throw 'wrong hint';}};var current=x.getAttributeNode('width'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='-7'||current.value!=='-2147483648'||records.length!==3||records[2].oldValue!=='author')throw 'once numeric conversion with current Attr';var order='';x.width={valueOf:function(){order+='v';return {};},toString:function(){order+='s';return '17';}};if(order!=='vs'||x.width!==17||current!==x.getAttributeNode('width'))throw 'number-hint fallback order';watch.takeRecords();var marker={},caught;try{x.width={valueOf:function(){x.setAttribute('width','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.getAttribute('width')!=='author effect'||records.length!==1||records[0].oldValue!=='17')throw 'abrupt numeric author effect';for(var bad of [Symbol('number'),BigInt(1)]){caught=false;try{x.width=bad;}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.getAttribute('width')!=='author effect')throw 'implicit numeric primitive refusal';}var hints='',value={};value[Symbol.toPrimitive]=function(hint){hints+=hint;return NaN;};x.width=value;if(hints!=='number'||x.width!==0||x.getAttribute('width')!=='0'||x.getAttribute('data-kind')!=='marker')throw 'number primitive hint';"#);}
#[test]
fn pre_width_concrete_brands_precede_conversion_and_author_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLPreElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'width'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('ul'),document.createElement('li'),document.createElement('img'),document.createElement('canvas'),document.getElementById('neighbor'),document.createElement('data'),document.createElementNS('urn:foreign','listing'),new Document().createElementNS('http://www.w3.org/1999/xhtml','LISTING')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'long getter concrete brand';caught=false;try{a.set.call(bad,{valueOf:function(){calls++;return 1;}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'long setter brand before conversion';}Object.defineProperty(x,'width',{value:'author',writable:true,configurable:true});a.set.call(x,3.9);if(x.width!=='author'||a.get.call(x)!==3||x.getAttribute('width')!=='3')throw 'canonical numeric authority';delete x.width;delete window.HTMLPreElement;var copy=x.cloneNode(false);if(x.width!==3||!(copy instanceof C)||Object.getPrototypeOf(copy)!==P||copy.width!==3||document.getElementById('neighbor').value!=='seed')throw 'saved canonical long interface';"#);}
