fn pre_width_raw_attribute_backing_and_numeric_normalization_keep_exact_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','listing')]){x.setAttribute('width','12\ud800Z');var attr=x.getAttributeNode('width');if(x.width!==12||attr.value.length!==4||attr.value.charCodeAt(2)!==55296)throw 'actual raw integer prefix';attr.nodeValue='-2\udfffZ';if(x.width!==-2||attr.value.length!==4||attr.value.charCodeAt(2)!==57343)throw 'raw Attr integer alias';var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.width=4294967295;var records=watch.takeRecords();if(x.width!==-1||attr.value!=='-1'||x.getAttributeNode('width')!==attr||records.length!==1||records[0].oldValue!=='-2\udfffZ'||records[0].oldValue.charCodeAt(2)!==57343)throw 'numeric normalization exact old backing';x.setAttribute('width','7\ud800');var copy=x.cloneNode(false);if(copy.width!==7||copy.getAttribute('width').length!==2||copy.getAttribute('width').charCodeAt(1)!==55296||copy.getAttributeNode('width')===attr)throw 'raw integer independent clone';copy.width=-0;if(copy.width!==0||copy.getAttribute('width')!=='0'||x.width!==7||attr.value.charCodeAt(1)!==55296)throw 'independent numeric clone write';}"#);}
