fn pre_width_native_adoption_copy_import_and_shallow_template_preserve_metadata(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),attr=x.getAttributeNode('width'),first=x.firstChild,copy=x.cloneNode(true),doc=new Document();if(copy.width!==-7||copy.firstChild===first||copy.getAttributeNode('width')===attr)throw 'actual numeric clone';doc.adoptNode(x);if(x.width!==-7||x.ownerDocument!==doc||attr.ownerDocument!==doc||x.firstChild!==first||x.getAttributeNode('width')!==attr)throw 'identity numeric adoption';var imported=document.importNode(x,true);if(imported.width!==-7||imported.ownerDocument!==document||imported.firstChild===first||imported.getAttributeNode('width')===attr)throw 'actual numeric import';document.adoptNode(x);document.body.appendChild(x);copy.width=42;if(x.width!==-7||copy.width!==42||x.firstChild!==first||x.getAttribute('data-kind')!=='marker')throw 'independent numeric lifecycle';var leaf=x.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.width!==-7||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('width')!=='-7')throw 'actual numeric template parking';");}
