fn pre_width_saved_child_origin_refuses_before_number_hooks_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),calls=0,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLPreElement.prototype,'width');a.set.call(x,2147483648);if(a.get.call(x)!==-2147483648)throw 'same origin signed accessor';");p.set_location(&crate::navigation::address("https://foreign-listing-width.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for code in ["a.get.call(x);","a.set.call(x,{valueOf:function(){calls++;return 1;}});"]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://listing-width.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.width!==-2147483648)throw 'origin refusal before coercion';a.set.call(x,-3.9);if(a.get.call(x)!==-3||x.getAttribute('width')!=='-3')throw 'fresh numeric owner recovery';");}
#[test]
fn pre_width_reads_charge_payload_and_deadline_without_copy_string_or_retained_growth(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','listing');"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,&format!("x.setAttribute('width','{}7');","0".repeat(128)));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine PRE")};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),2=>p.state.host_work=16,_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.pre_width_get(object);if mode==3{assert!(matches!(result,Ok(Value::Number(7.0))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.pre_width_get(object),Ok(Value::Number(7.0))));}}}
