fn pre_width_interface_descriptors_retain_the_real_html_chain(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLPreElement,P=C.prototype,g=Object.getOwnPropertyDescriptor(window,'HTMLPreElement'),a=Object.getOwnPropertyDescriptor(C,'prototype'),tag=Object.getOwnPropertyDescriptor(P,Symbol.toStringTag);if(g.enumerable||!g.writable||!g.configurable||g.value!==C||a.writable||a.enumerable||a.configurable||a.value!==P||tag.value!=='HTMLPreElement'||tag.writable||tag.enumerable||!tag.configurable||P.constructor!==C)throw 'preformatted canonical descriptors';");}
#[test]
fn pre_width_exact_factories_saved_constructor_and_independent_clone(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLPreElement,P=C.prototype,x=document.getElementById('list'),doc=new Document(),y=doc.createElementNS('http://www.w3.org/1999/xhtml','t:xmp');if(!(y instanceof C)||Object.getPrototypeOf(y)!==P||y.width!==0||doc.createElementNS('http://www.w3.org/1999/xhtml','XMP') instanceof C||document.createElementNS('urn:foreign','xmp') instanceof C)throw 'exact preformatted factory namespaces';delete window.HTMLPreElement;var upper=document.createElement('XMP'),copy=x.cloneNode(false);if(!(upper instanceof C)||upper.localName!=='xmp'||Object.getPrototypeOf(upper)!==P||!(copy instanceof C)||copy.width!==-7||copy.getAttributeNode('width')===x.getAttributeNode('width'))throw 'saved canonical preformatted factory';copy.width=42;if(x.width!==-7||copy.width!==42)throw 'independent preformatted metadata';");}

